    return n, m, s, t, edges

def build_graph(n, edges):
    adj = defaultdict(list)
    edge_indices = {}

    for idx, (u, v, _) in enumerate(edges):
        # Store multiple edges between same pair
        adj[u].append((v, idx + 1))
        adj[v].append((u, idx + 1))

    return adj

def can_reach(n, adj, removed_edges, s, t):
    """Check if t is reachable from s after removing edges"""
    visited = [False] * (n + 1)
    queue = deque([s])
    visited[s] = True

    while queue:
        u = queue.popleft()
        if u == t:
            return True

        for v, _ in adj[u]:
            if v is None or v in removed_edges:
                continue

            # Edge exists with this index in removed set
            if (u, v) in removed_edges or (v, u) in removed_edges:
                # Actually we need to check edge index, not edge in both directions
                continue

            if not visited[v]:
                visited[v] = True
                queue.append(v)

    return visited[t]

def build_clean_adj(n, edges):
    """Build adjacency list without removed edges"""
    adj = defaultdict(list)
    edge_map = {}  # edge index -> (u, v)

    for idx, edge in enumerate(edges):
        u, v, _ = edge
        adj[u].append((v, idx + 1))
        adj[v].append((u, idx + 1))
        edge_map[idx + 1] = (u, v)

    return adj, edge_map

def is_connected(n, adj, removed_edges, edge_map, s, t):
    """Check if t is reachable from s using BFS, skipping removed edges"""
    visited = set([s])
    queue = deque([s])

    while queue:
        u = queue.popleft()
        if u == t:
            return True

        for v, edge_idx in adj[u]:
            if edge_idx in removed_edges:
                continue
            if v not in visited:
                visited.add(v)
                queue.append(v)

    return t in visited

