def is_gp(seq):
    n = len(seq)

    if n == 0:
        return True
    if all(x == 0 for x in seq):
        return True
    if n <= 2:
        return True

    # If first element is zero
    if seq[0] == 0:
        # If any non-zero element follows, not a GP
        if any(x != 0 for x in seq[1:]):
            return False
        return True

    # Calculate ratio as fraction from first two elements
    g = gcd(abs(seq[0]), abs(seq[1]))
    ratio_num = seq[1] // g
    ratio_den = seq[0] // g

    # Verify all elements follow the pattern
    prev = seq[0]
    if ratio_den == 0:
        # Division by zero, can't be GP
        return False

    for i in range(1, n):
        if ratio_num == 0:
            # Ratio is 0, so all subsequent elements must be 0
            if seq[i] != 0:
                return False
        else:
            cross_check = ratio_den * seq[i] - ratio_num * prev
            if cross_check != 0:
                return False
        prev = seq[i]

    return True


def gcd(a, b):
    while b:
        a, b = b, a % b
    return abs(a)

