def solution(input_str):
    lines = input_str.strip().split('\n')
    n, m = map(int, lines[0].split())

    # ans[j] = earliest time-step to get exactly j bananas, or -1 if impossible
    ans = [-1] * (m + 1)

    # current_k: set of banana counts reachable at the current time step
    current_k = {0}

    for t in range(1, n + 1):
        new_k = set()
        parts = lines[t - 1].split()
        t_type = int(parts[0])
        x_prime = int(parts[1])
        y = int(parts[2])
        x = x_prime / 100000.0

        for k in current_k:
            # Try applying the operation 0 to y times
            for a in range(y + 1):
                if a == 0:
                    next_k = k
                elif t_type == 1:
                    # Type 1: add x, apply a times with ceiling
                    acc = k
                    for _ in range(a):
                        acc = math.ceil(acc + x)
                    next_k = acc
                else:
                    # Type 2: multiply by x, apply a times with ceiling
                    acc = k
                    for _ in range(a):
                        acc = math.ceil(acc * x)
                    next_k = acc

                if next_k <= m:
                    if ans[next_k] == -1:
                        ans[next_k] = t
                new_k.add(next_k)

        current_k = new_k

    return ' '.join(map(str, ans[1:])) + '\n'

