    lines = input_str.strip().split('\n')
    if not lines:
        return "-1\n"

    n, m = map(int, lines[0].split())

    # Union-Find to find connected components
    parent = list(range(n + 1))
    comp_size = [1] * (n + 1)

    def find(x):
        if parent[x] != x:
            parent[x] = find(parent[x])
        return parent[x]

    def union(x, y):
        px, py = find(x), find(y)
        if px == py:
            return
        if comp_size[px] < comp_size[py]:
            px, py = py, px
        parent[py] = px
        comp_size[px] += comp_size[py]

    # Process each edge
    for i in range(1, m + 1):
        if i < len(lines):
            u, v = map(int, lines[i].split())
            union(u, v)

    # Collect unique component sizes
    comp_sizes = set()
    for i in range(1, n + 1):
        comp_sizes.add(comp_size[find(i)])

    # Generate lucky numbers up to n
    lucky = set()
    q_lucky = [4, 7]
    while q_lucky:
        num = q_lucky.pop(0)
        if num <= n:
            lucky.add(num)
            for digit in [4, 7]:
                new_num = num * 10 + digit
                if new_num <= n:
                    q_lucky.append(new_num)

    if not lucky:
        return "-1\n"

    # DP: dp[s] = minimum components needed to achieve sum s
    INF = n + 1
    dp = [INF] * (n + 1)
    dp[0] = 0

    for sz in comp_sizes:
        for s in range(n, sz - 1, -1):
            if dp[s - sz] != INF:
                dp[s] = min(dp[s], dp[s - sz] + 1)

    # Find minimum components needed for any lucky number
    ans = INF
    for l in lucky:
        if dp[l] < ans:
            ans = dp[l]

    if ans == INF:
        return "-1\n"

    # Answer is components - 1 (roads needed)
    return f"{max(0, ans - 1)}\n"

