        nonlocal turned_off_count

        if x == current_pos[0] and y == current_pos[1]:
            return lit_count == 0

        if (x, y) in visited_position:
            return False

        visited_position.add((x, y))

        # Current cell operations
        if grid[x][y] == 1 and lit_count > 0:
            actions.extend(['2'])  # Turn off
            lit_count -= 1

        # Try directions
        directions = [('L', 0, -1), ('R', 0, 1), ('U', -1, 0), ('D', 1, 0)]
        for move_dir, dx, dy in directions:
            nx, ny = x + dx, y + dy

            if 1 <= nx <= n and 1 <= ny <= n and (nx, ny) not in visited_position:
                # Need visibility or can turn on light to create visibility
                can_move = check_visibility(x, y, move_dir, n, grid) or (grid[nx][ny] == 1)

                if can_move:
                    # Try the move - track potential light turns
                    if not can_move and grid[x][y] == 0:
                        actions.append('1')
                    else:
