                    # Backtrack
                    visited_position.remove((nx, ny))
                    if not can_move or grid[nx][ny] == 0:
                        if actions and actions[-1] == move_dir:
                            actions.pop()
            else:
                continue

        visited_position.remove((x, y))
        return False

    success = dfs(current_pos[0], current_pos[1], [], lit_cells_count)

