    for i in range(1, len(lines)):
        parts = lines[i].split()
        if len(parts) >= 3:
            u, v, w = int(parts[0]), int(parts[1]), int(parts[2])
            edges.append((w, u, v, i + 1))

    # Not enough edges to form a spanning tree
    if len(edges) < n - 1:
        return "-1"

    # Union-Find with path compression
    parent = list(range(n + 1))
    def find(x):
        root = x
        while parent[root] != root:
            root = parent[root]
        while parent[x] != root:
            parent[x], x = root, parent[x]
        return root

    def unite(x, y):
        px, py = find(x), find(y)
        if px != py:
            parent[px] = py
            return True
        return False

    # Separate capital edges (those connected to city 1) from others
    capital_edges = []
    regular_edges = []
    for w, u, v, idx in edges:
        if u == 1 or v == 1:
            capital_edges.append((w, u, v, idx))
        else:
            regular_edges.append((w, u, v, idx))

    # Sort both lists by weight
    capital_edges.sort()
    regular_edges.sort()

    # Combine all edges sorted by weight
    all_edges = capital_edges + regular_edges
    all_edges.sort(key=lambda x: x[0])

    # Select exactly the k smallest capital edges first
    mst_edges = []
    capital_used = 0

    for w, u, v, idx in all_edges:
        if capital_used >= k and (u == 1 or v == 1):
            continue  # Skip extra capital edges

        if unite(u, v):
            mst_edges.append(idx)
            if u == 1 or v == 1:
                capital_used += 1

    # Verify solution
    if len(mst_edges) != n - 1:
        return "-1"

    # Check all cities are connected
    roots = {find(i) for i in range(1, n + 1)}
    if len(roots) > 1:
        return "-1"

    # Output result
    result = sorted(mst_edges)
    return f"{len(result)}\n{' '.join(map(str, result))}\n"

