def mat_mul(A, B, mod):
    C = [[0]*5 for _ in range(5)]
    for i in range(5):
        for j in range(5):
            for k in range(5):
                C[i][j] = (C[i][j] + A[i][k] * B[k][j]) % mod
    return C

def mat_pow(A, p, mod):
    result = [[0]*5 for _ in range(5)]
    for i in range(5):
        result[i][i] = 1
    base = A
    while p > 0:
        if p & 1:
            result = mat_mul(result, base, mod)
        base = mat_mul(base, base, mod)
        p //= 2
    return result

