    from collections import defaultdict

    lines = input_str.strip().split('\n')
    if len(lines) < 1:
        return "-1"

    n, m, k = map(int, lines[0].split())

    # Handle case where k >= n - path of 1 vertex satisfies requirement
    if k >= n:
        return "PATH\n1\n"

    # Build adjacency list
    adj = defaultdict(list)
    for line in lines[1:]:
        if not line.strip():
            continue
        parts = line.strip().split()
        if len(parts) >= 2:
            u, v = int(parts[0]), int(parts[1])
            adj[u].append(v)
            adj[v].append(u)

    # Target path length is ceiling of n/k
    target_len = (n + k - 1) // k if k < n else 1

    # If k >= n, any single vertex works as a path
    if k >= n:
        return "PATH\n1\n1\n"

    # Iterative DFS to find longest simple path
    max_path = []

    def find_path(start):
        nonlocal max_path
        stack = [(start, [start], set([start]))]

        while stack:
            u, path, visited = stack[-1]
            path_len = len(path)

            if path_len > len(max_path):
                max_path = path[:]

            adj_sorted = sorted(adj[u], key=lambda x: -len(adj[x]), reverse=True)

            for v in adj_sorted:
                if v not in visited:
                    stack.append((v, path + [v], visited | {v}))

                # Pruning: if unvisited neighbors, try them
                break

            # If no unvisited neighbors, pop from stack
            if all(v in visited for v in adj[u]):
                stack.pop()

    # Try from each node
    for node in range(1, n + 1):
        if node in adj:
            find_path(node)
            if len(max_path) >= target_len:
                break

    # Output path if found
    if len(max_path) >= target_len:
        return "PATH\n{}\n{}\n".format(len(max_path), " ".join(map(str, max_path[:target_len])))

    # Find cycles using DFS with recursion tracking
    cycles = []
    visited = set()

    def dfs_cycles(u, parent, path, in_stack):
        visited.add(u)
        in_stack[u] = True
        path.append(u)

        for v in adj[u]:
            if v == parent:
                continue

            if v in in_stack:
                # Found back edge - cycle detected
                idx = path.index(v)
                cycle = path[idx:]
                if len(cycle) >= 3 and len(cycle) % 3 != 0:
                    cycles.append(cycle)
            elif v not in visited:
                dfs_cycles(v, u, path, in_stack)

        path.pop()
        in_stack[u] = False
        visited.discard(u)

    # Find cycles from each node
    for node in sorted(adj.keys(), key=lambda x: -len(adj[x])):
        if len(adj[node]) >= 3:
            dfs_cycles(node, -1, [], {})
            if len(cycles) >= k:
                break

    # Select k cycles with unique representatives
    selected = []
    reps_available = set()

    for cycle in cycles:
        if len(selected) >= k:
            break

        # Try to find a representative (vertex not used as rep in other cycles)
        found_rep = False
        for rep in cycle:
            if rep not in reps_available:
                found_rep = True
                break

        if not found_rep:
            continue

        # Mark representative as used for all vertices in this cycle
        for v in cycle:
            reps_available.add(v)

        selected.append(cycle)

    if len(selected) >= k:
        result = "CYCLES"
        for c in selected[:k]:
            result += "\n{}\n{}\n".format(len(c), " ".join(map(str, c)))
        return result

    return "-1"

