def solution(data):
    """
    Calculate the number of valid permutations with no fixed points
    that can complete the given partial permutation.
    """
    from typing import List

    lines = data.strip().split('\n')
    n = int(lines[0])
    arr = list(map(int, lines[1].split()))

    # Identify which positions have -1 (1-indexed positions for logic)
    missing_pos = [i + 1 for i, x in enumerate(arr) if x == -1]

    # Find which values (1 to n) are available (not present in array)
    present = set(x for x in arr if x != -1)
    available = set(range(1, n + 1)) - present

    n_missing = len(missing_pos)
    n_available = len(available)

    # n_missing should equal n_available (all available values fill missing positions)
    n1 = n_missing

    # Precompute factorials
    MOD = 1000000007

    # For derangement of n elements: D(n) = sum_{i=0 to n} (-1)^i * C(n, i) * (n - i)!
    # = sum_{i=0 to n} (-1)^i * n! / i!

    ans = 0
    for i in range(n1 + 1):
        # C(n1, i) = n1! / (i! * (n1-i)!)
        # C(n1, i) * (n1 - i)! = n1! / i!

        # Calculate n1! / i! mod MOD
        def compute_factorial_inv():
            fact = 1
            for k in range(1, n1 + 1):
                fact = (fact * k) % MOD
            return fact, i

        fact_n1, i = compute_factorial_inv()
        fact_i = 1
        for k in range(1, i + 1):
            fact_i = (fact_i * k) % MOD

        inv_fact_i = pow(fact_i, MOD - 2, MOD)
        terms = (fact_n1 * inv_fact_i) % MOD

        if i % 2 == 1:
            ans = (ans - terms + MOD) % MOD
        else:
            ans = (ans + terms) % MOD

    return str(ans)


