    Computes the maximum product of component sizes when deleting
    edges from a tree.
    """
    lines = input_str.strip().split('\n')
    n = int(lines[0])

    if n == 1:
        return '1'

    adj = [[] for _ in range(n + 1)]
    for i in range(1, len(lines)):
        line = lines[i].strip()
        if line:
            u, v = map(int, line.split())
            adj[u].append(v)
            adj[v].append(u)

    parent = [0] * (n + 1)
    order = []
    stack = [1]
    visited = [False] * (n + 1)
    visited[1] = True

    while stack:
        u = stack.pop()
        order.append(u)
        for v in adj[u]:
            if not visited[v]:
                visited[v] = True
                parent[v] = u
                stack.append(v)

    children = [[] for _ in range(n + 1)]
    for u in order:
        for v in adj[u]:
            if v != parent[u]:
                children[u].append(v)

    from functools import lru_cache

    @lru_cache(maxsize=None)
    def dp(u):
        if not children[u]:
            return {1: 1}

        result = {1: 1}

        for v in children[u]:
            child_states = dp(v)
            new_result = {}

            for sz_u in result:
                best_child = max(child_states.values())
                new_result[sz_u] = max(new_result.get(sz_u, 0), result[sz_u] * best_child)

                for sz_v, prod_v in child_states.items():
                    merged = sz_u + sz_v
                    combined = result[sz_u] * prod_v
                    new_result[merged] = max(new_result.get(merged, 0), combined)

            result = new_result

        return result

    states = dp(1)
    if not states:
        return '1'
    return str(max(states.values()))

