    n, l, r = map(int, text.strip().split())

    if n == 1:
        return str(r - l + 1) + '\n'

    if n == 2:
        return str((r - l + 1) * (r - l)) + '\n'

    if l == r:
        return "0\n"

    if n >= 4:
        return "0\n"

    # For n = 3
    count = 0
    for b in range(l + 1, r):
        # a must be in [l, b-1] AND [ceil(b^2/r), floor(b^2/l)]
        lower_a = max(l, (b * b + r - 1) // r)  # ceil(b^2/r)
        upper_a = min(b - 1, b * b // l)  # floor(b^2 / l)

        if upper_a >= lower_a:
            count += upper_a - lower_a + 1

    return str(count) + '\n'

