    current_r, current_c = 0, 0  # 0-indexed

    # Predict and verify the path
    target = finish

    # Use BFS - but also account for potential swaps
    # Since we need to output correct directions, we'll try each swap config
    best_path = None
    best_config = (False, False)

    def find_with_config(swap_lr, swap_ud):
        q = deque([(current_r, current_c, [])])
        visited = {(current_r, current_c)}

        def get_direction():
            for dr, dc, name in [(0, 1, 'R'), (0, -1, 'L'), (1, 0, 'D'), (-1, 0, 'U')]:
                if swap_lr and name in ['L', 'R']:
                    name = 'R' if name == 'L' else 'L'
                if swap_ud and name in ['U', 'D']:
                    name = 'D' if name == 'U' else 'U'
                yield dr, dc, name

        while q:
            rr, cc, path = q.popleft()
            if (rr, cc) == target:
                return path

            for dr, dc, move in get_direction():
                nr, nc = rr + dr, cc + dc
                if 0 <= nr < n and 0 <= nc < m:
                    if grid[nr][nc] != '*' and grid[nr][nc] != 'F':
                        if (nr, nc) not in visited:
                            visited.add((nr, nc))
                            q.append((nr, nc, path + [move]))
                    elif grid[nr][nc] == 'F':
                        return path + [move]

        return None

    for config in [(False, False), (True, False), (False, True), (True, True)]:
        path = find_with_config(*config)
        if path:
            best_path = path
            best_config = config
            break

