from functools import lru_cache

def solution(s):
    line = s.strip()
    if not line:
        return ""

    parts = line.split()
    if len(parts) != 3:
        return ""

    a, b, n = int(parts[0]), int(parts[1]), int(parts[2])

    # Edge case: if a = 1 or b = 1, 1^ anything = 1 < n, so game never ends
    if a == 1 or b == 1:
        return "Missing\n\n"

    @lru_cache(maxsize=None)
    def can_win(x, y):
        # If current position has x^y >= n, we've already made a losing move
        if x ** y >= n:
            return False

        # Try both moves - if any move leads to opponent losing, we win
        win_by_adding_box = False
        win_by_adding_item = False

        # Move 1: add a box (x+1, y)
        if (x + 1) ** y < n:
            if not can_win(x + 1, y):
                win_by_adding_box = True

        # Move 2: add an item (x, y+1)
        if x ** (y + 1) < n:
            if not can_win(x, y + 1):
                win_by_adding_item = True

        return win_by_adding_box or win_by_adding_item

    if can_win(a, b):
        return "Stas\n\n"
    else:
        return "Masha\n\n"

